    20→package org.apache.druid.segment.filter;
    21→
    22→import com.google.common.base.Predicate;
    23→import com.google.common.collect.ImmutableSet;
    24→import org.apache.druid.query.BitmapResultFactory;
    25→import org.apache.druid.query.filter.BitmapIndexSelector;
    26→import org.apache.druid.query.filter.Filter;
    27→import org.apache.druid.query.filter.FilterTuning;
    28→import org.apache.druid.query.filter.JavaScriptDimFilter;
    29→import org.apache.druid.query.filter.ValueMatcher;
    30→import org.apache.druid.segment.ColumnSelector;
    31→import org.apache.druid.segment.ColumnSelectorFactory;
    32→import org.mozilla.javascript.Context;
    33→
    34→import java.util.Objects;
    35→import java.util.Set;
    36→
    37→public class JavaScriptFilter implements Filter
    38→{
    39→  private final String dimension;
    40→  private final JavaScriptDimFilter.JavaScriptPredicateFactory predicateFactory;
    41→  private final FilterTuning filterTuning;
    42→
    43→  public JavaScriptFilter(
    44→      String dimension,
    45→      JavaScriptDimFilter.JavaScriptPredicateFactory predicate,
    46→      FilterTuning filterTuning
    47→  )
    48→  {
    49→    this.dimension = dimension;
    50→    this.predicateFactory = predicate;
    51→    this.filterTuning = filterTuning;
    52→  }
    53→
    54→  @Override
    55→  public <T> T getBitmapResult(BitmapIndexSelector selector, BitmapResultFactory<T> bitmapResultFactory)
    56→  {
    57→    final Context cx = Context.enter();
    58→    try {
    59→      return Filters.matchPredicate(dimension, selector, bitmapResultFactory, makeStringPredicate(cx));
    60→    }
    61→    finally {
    62→      Context.exit();
    63→    }
    64→  }
    65→
    66→  @Override
    67→  public double estimateSelectivity(BitmapIndexSelector indexSelector)
    68→  {
    69→    final Context cx = Context.enter();
    70→    try {
    71→      return Filters.estimateSelectivity(dimension, indexSelector, makeStringPredicate(cx));
    72→    }
    73→    finally {
    74→      Context.exit();
    75→    }
    76→  }
    77→
    78→  private Predicate<String> makeStringPredicate(final Context context)
    79→  {
    80→    return new Predicate<String>()
    81→    {
    82→      @Override
    83→      public boolean apply(String input)
    84→      {
    85→        return predicateFactory.applyInContext(context, input);
    86→      }
    87→    };
    88→  }
    89→
    90→  @Override
    91→  public ValueMatcher makeMatcher(ColumnSelectorFactory factory)
    92→  {
    93→    // suboptimal, since we need create one context per call to predicate.apply()
    94→    return Filters.makeValueMatcher(factory, dimension, predicateFactory);
    95→  }
    96→
    97→  @Override
    98→  public boolean supportsBitmapIndex(BitmapIndexSelector selector)
    99→  {
   100→    return selector.getBitmapIndex(dimension) != null;
   101→  }
   102→
   103→  @Override
   104→  public boolean shouldUseBitmapIndex(BitmapIndexSelector selector)
   105→  {
   106→    return Filters.shouldUseBitmapIndex(this, selector, filterTuning);
   107→  }
   108→
   109→  @Override
   110→  public boolean supportsSelectivityEstimation(ColumnSelector columnSelector, BitmapIndexSelector indexSelector)
   111→  {
   112→    return Filters.supportsSelectivityEstimation(this, dimension, columnSelector, indexSelector);
   113→  }
   114→
   115→  @Override
   116→  public Set<String> getRequiredColumns()
   117→  {
   118→    return ImmutableSet.of(dimension);
   119→  }
   120→
   121→  @Override
   122→  public boolean equals(Object o)
   123→  {
   124→    if (this == o) {
   125→      return true;
   126→    }
   127→    if (o == null || getClass() != o.getClass()) {
   128→      return false;
   129→    }
   130→    JavaScriptFilter that = (JavaScriptFilter) o;
   131→    return Objects.equals(dimension, that.dimension) &&
   132→           Objects.equals(predicateFactory, that.predicateFactory) &&
   133→           Objects.equals(filterTuning, that.filterTuning);
   134→  }
   135→
   136→  @Override
   137→  public int hashCode()
   138→  {
   139→    return Objects.hash(dimension, predicateFactory, filterTuning);
   140→  }
   141→}
